    quizQuestions: [
      { question: "She usually _______ (go) to work by bus.", options: ["go", "goes", "going", "went"], correct: "goes", explanation: "Vì chủ ngữ là 'She' (số ít) và trạng từ 'usually' chỉ thói quen hiện tại." },
      { question: "Water _______ (boil) at 100 degrees Celsius.", options: ["boil", "boils", "boiling", "boiled"], correct: "boils", explanation: "Diễn tả một chân lý, sự thật hiển nhiên nên chia hiện tại đơn ngôi thứ 3 số ít." },
      { question: "They _______ (not like) fast food.", options: ["don't like", "doesn't like", "not like", "didn't like"], correct: "don't like", explanation: "Với chủ ngữ 'They', ta dùng trợ động từ 'do not' (don't) ở hiện tại đơn." },
      { question: "_______ he play soccer on Sundays?", options: ["Do", "Does", "Is", "Did"], correct: "Does", explanation: "Chủ ngữ là 'he' nên dùng trợ động từ nghi vấn 'Does'." },
      { question: "The earth _______ (revolve) around the sun.", options: ["revolve", "revolves", "revolving", "revolved"], correct: "revolves", explanation: "Sự thật hiển nhiên về vũ trụ, chia hiện tại đơn ngôi thứ 3 số ít." },
      { question: "We _______ (be) engineers in this factory.", options: ["am", "is", "are", "be"], correct: "are", explanation: "Chủ ngữ 'We' đi với động từ to be 'are' ở hiện tại." },
      { question: "My father never _______ (drink) coffee at night.", options: ["drink", "drinks", "drinking", "drank"], correct: "drinks", explanation: "Chủ ngữ 'My father' (số ít) đi kèm từ chỉ tần suất 'never' ở hiện tại đơn." },
      { question: "Do you _______ (know) where the ventilation shaft is?", options: ["know", "knows", "knowing", "knew"], correct: "know", explanation: "Sau trợ động từ 'Do/Does' trong câu hỏi, động từ chính giữ nguyên mẫu." },
      { question: "The sun _______ (not rise) in the west.", options: ["doesn't rise", "don't rise", "not rises", "isn't rise"], correct: "doesn't rise", explanation: "Chủ ngữ 'The sun' số ít, câu phủ định chân lý dùng 'doesn't + V-inf'." },
      { question: "Normally, the steam engine _______ (start) quickly.", options: ["start", "starts", "starting", "started"], correct: "starts", explanation: "Trạng từ 'Normally' chỉ thói quen/sự việc thông thường, động từ thêm 's'." }
    ]
